ask_secret KOALA_ANDROID_MAPS_API_KEY_PRODUCTION "Production Android Maps API anahtarını gir:"
set_secret KOALA_ANDROID_KEYSTORE_BASE64 "$KOALA_ANDROID_KEYSTORE_BASE64"
set_secret KOALA_ANDROID_KEYSTORE_PASSWORD "$KOALA_ANDROID_KEYSTORE_PASSWORD"
set_secret KOALA_ANDROID_KEY_ALIAS "$KOALA_ANDROID_KEY_ALIAS"
set_secret KOALA_ANDROID_KEY_PASSWORD "$KOALA_ANDROID_KEY_PASSWORD"
set_secret PLAY_SERVICE_ACCOUNT_JSON "$PLAY_SERVICE_ACCOUNT_JSON"
set_secret KOALA_ANDROID_MAPS_API_KEY_PRODUCTION "$KOALA_ANDROID_MAPS_API_KEY_PRODUCTION"

stage "Play App Signing parmak izi"
say "Asset Links, upload key'i değil kullanıcının cihazındaki APK'yı imzalayan Play App Signing sertifikasını kullanır."
open_url "https://play.google.com/console/developers"
step "Koala → Setup → App integrity → App signing key certificate yoluna git."
step "SHA-256 certificate fingerprint değerini kopyala; bu değer publictir."
ask PLAY_APP_SIGNING_SHA256 "Play App Signing SHA-256 değerini yapıştır:"
while [[ ! "$PLAY_APP_SIGNING_SHA256" =~ ^([A-Fa-f0-9]{2}:){31}[A-Fa-f0-9]{2}$ ]]; do
  warn "Beklenen biçim iki haneli 32 hex grubudur; örnek değer gösterilmiyor."
  ask PLAY_APP_SIGNING_SHA256 "Play App Signing SHA-256 değerini yeniden yapıştır:"
done
set_repo_var "is-koala/koala-web" ANDROID_APP_LINKS_PACKAGE_NAME "com.iskoala.koala"
set_repo_var "is-koala/koala-web" ANDROID_APP_LINKS_SHA256_CERT_FINGERPRINTS "$PLAY_APP_SIGNING_SHA256"
step "koala-web PR'ı yayımlandıktan sonra iskoala.com üzerinde 200/application-json doğrula."
pause "Web tarafındaki fingerprint değişikliği PR'a alındığında Enter'a bas."

stage "Apple kimlik, imzalama ve API erişimi"
say "Production App ID Associated Domains yetkisi taşımalı; yenilenen profile ve bütün private materyal GitHub secret'a gider."
open_url "https://developer.apple.com/account/resources/identifiers/list"
step "com.iskoala.koala App ID'sini aç, Associated Domains capability'sini etkinleştir ve kaydet."
step "Application Identifier Prefix değerini kopyala; AASA appID alanı bu public prefix ile bundle ID'yi birleştirir."
ask APPLE_APPLICATION_IDENTIFIER_PREFIX "Application Identifier Prefix değerini gir:"
while [[ ! "$APPLE_APPLICATION_IDENTIFIER_PREFIX" =~ ^[A-Z0-9]{5,20}$ ]]; do
  warn "Application Identifier Prefix 5-20 büyük harf veya rakam içermelidir."
  ask APPLE_APPLICATION_IDENTIFIER_PREFIX "Application Identifier Prefix değerini yeniden gir:"
done
set_repo_var "is-koala/koala-web" APPLE_APP_IDENTIFIER "$APPLE_APPLICATION_IDENTIFIER_PREFIX.com.iskoala.koala"
open_url "https://developer.apple.com/account/resources/profiles/list"
step "Production App Store provisioning profile'ını capability değişikliğinden sonra yeniden üret ve indir."
step "Apple Distribution sertifikasını private key'iyle P12 olarak dışa aktar; P12'yi repo dışında sakla."
step "P12 ve mobileprovision dosyalarını ayrı ayrı tek satır base64'e çevir."
ask_secret APPLE_DISTRIBUTION_CERTIFICATE_BASE64 "Distribution P12 base64 değerini yapıştır:"
ask_secret APPLE_DISTRIBUTION_CERTIFICATE_PASSWORD "P12 parolasını gir:"
ask_secret APPLE_PROVISIONING_PROFILE_BASE64 "Production mobileprovision base64 değerini yapıştır:"
ask_secret APPLE_TEAM_ID "Apple Team ID değerini gir:"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
