ask_secret APP_STORE_CONNECT_API_KEY_ID "App Store Connect API Key ID değerini gir:"
ask_secret APP_STORE_CONNECT_API_ISSUER_ID "App Store Connect API Issuer ID değerini gir:"
ask_secret APP_STORE_CONNECT_API_KEY_P8_BASE64 "P8 private key base64 değerini yapıştır:"
step "Production iOS Maps anahtarının yalnız com.iskoala.koala bundle kimliği ve gerekli Maps API'leriyle kısıtlı olduğunu doğrula."
ask_secret KOALA_IOS_MAPS_API_KEY_PRODUCTION "Production iOS Maps API anahtarını gir:"
set_secret APPLE_DISTRIBUTION_CERTIFICATE_BASE64 "$APPLE_DISTRIBUTION_CERTIFICATE_BASE64"
set_secret APPLE_DISTRIBUTION_CERTIFICATE_PASSWORD "$APPLE_DISTRIBUTION_CERTIFICATE_PASSWORD"
set_secret APPLE_PROVISIONING_PROFILE_BASE64 "$APPLE_PROVISIONING_PROFILE_BASE64"
set_secret APPLE_TEAM_ID "$APPLE_TEAM_ID"
