set_secret APP_STORE_CONNECT_API_ISSUER_ID "$APP_STORE_CONNECT_API_ISSUER_ID"
set_secret APP_STORE_CONNECT_API_KEY_P8_BASE64 "$APP_STORE_CONNECT_API_KEY_P8_BASE64"
set_secret KOALA_IOS_MAPS_API_KEY_PRODUCTION "$KOALA_IOS_MAPS_API_KEY_PRODUCTION"

stage "GitHub production ortam kapısı"
